#!/usr/bin/env bash
# Question 1: Control plane after maintenance. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q1_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF

case "${Q1_FAULT}" in
  etcd-cert-path)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --cert-file=/etc/kubernetes/pki/etcd/server)\.crt$#\1.cert#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '- --cert-file=/etc/kubernetes/pki/etcd/server.cert$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  etcd-key-path)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --key-file=/etc/kubernetes/pki/etcd/server)\.key$#\1.pem#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '- --key-file=/etc/kubernetes/pki/etcd/server.pem$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  etcd-trusted-ca-path)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --trusted-ca-file=/etc/kubernetes/pki/etcd/ca)\.crt$#\1.pem#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '- --trusted-ca-file=/etc/kubernetes/pki/etcd/ca.pem$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  etcd-client-urls)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E '/--listen-client-urls=/s/:2379/:2378/g' /etc/kubernetes/manifests/etcd.yaml
    sed -i -E '/--advertise-client-urls=/s/:2379/:2378/g' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '--listen-client-urls=.*:2378' /etc/kubernetes/manifests/etcd.yaml || { echo "could not break listen-client-urls" >&2; exit 1; }
    grep -qE -- '--advertise-client-urls=.*:2378' /etc/kubernetes/manifests/etcd.yaml || { echo "could not break advertise-client-urls" >&2; exit 1; }
    ;;
  etcd-data-dir)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --data-dir=)/var/lib/etcd$#\1/var/lib/etcd-broken#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '- --data-dir=/var/lib/etcd-broken$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  etcd-image-tag)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    grep -oE 'etcd:[^[:space:]"]+' /etc/kubernetes/manifests/etcd.yaml | head -1 > "/var/tmp/cka-q1.etcd-image"
    sed -i -E 's#^([[:space:]]*image: [^[:space:]]*etcd:)[^[:space:]]+$#\1v0.0.0#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- 'etcd:v0\.0\.0$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  etcd-peer-urls)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E '/--listen-peer-urls=/s/:2380/:2381/g' /etc/kubernetes/manifests/etcd.yaml
    sed -i -E '/--initial-advertise-peer-urls=/s/:2380/:2381/g' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '--listen-peer-urls=.*:2381' /etc/kubernetes/manifests/etcd.yaml || { echo "could not break listen-peer-urls" >&2; exit 1; }
    grep -qE -- '--initial-advertise-peer-urls=.*:2381' /etc/kubernetes/manifests/etcd.yaml || { echo "could not break initial-advertise-peer-urls" >&2; exit 1; }
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q1_FAULT}" in
  etcd-cert-path)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-key-path)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-trusted-ca-path)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-client-urls)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-data-dir)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-image-tag)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-peer-urls)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
esac
